public static int computeUTF8Size(final String str, final int index, final int len) {
    int size = 0;
    for (int i = 0; i < len; i++) {
        final char c = str.charAt(index + i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            final char d = str.charAt(index + i + 1);
            if (Character.isLowSurrogate(d)) {
                size += 4;
                i++;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

