public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    // Find the last dot
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }

    // Check whether there is a directory separator after the last dot
    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator > lastDot) {
        return -1;
    }

    // We have found the extension
    return lastDot;
}

