public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (FileInputStream fis = new FileInputStream(file)) {
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(fis, timeRange.getStartTime(), timeRange.getEndTime());
            threadSnapshots.add(threadSnapshot);
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IOException("Failed to read thread snapshots from file", e);
    }
    return threadSnapshots;
}
